CREATE TABLE IF NOT EXISTS compute_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS compute_accounts(address TEXT PRIMARY KEY,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),held INTEGER NOT NULL DEFAULT 0 CHECK(held>=0 AND held<=balance),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_challenges(id TEXT PRIMARY KEY,address TEXT NOT NULL,message TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS compute_sessions(hash TEXT PRIMARY KEY,address TEXT NOT NULL REFERENCES compute_accounts(address),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_keys(id TEXT PRIMARY KEY,address TEXT NOT NULL REFERENCES compute_accounts(address),hash TEXT UNIQUE NOT NULL,prefix TEXT NOT NULL,name TEXT NOT NULL,models TEXT NOT NULL,scopes TEXT NOT NULL,daily_limit INTEGER NOT NULL,monthly_limit INTEGER NOT NULL,rpm INTEGER NOT NULL,concurrency INTEGER NOT NULL,created INTEGER NOT NULL,revoked INTEGER);
CREATE TABLE IF NOT EXISTS compute_ledger(id TEXT PRIMARY KEY,address TEXT NOT NULL REFERENCES compute_accounts(address),delta INTEGER NOT NULL,kind TEXT NOT NULL,reference TEXT UNIQUE NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_requests(id TEXT PRIMARY KEY,address TEXT NOT NULL REFERENCES compute_accounts(address),key_id TEXT REFERENCES compute_keys(id),idem TEXT NOT NULL,fingerprint TEXT NOT NULL,model TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('reserved','dispatching','completed','failed','unknown')),reserved INTEGER NOT NULL,charged INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,provider_request TEXT,created INTEGER NOT NULL,updated INTEGER NOT NULL,latency_ms INTEGER,error_code TEXT,UNIQUE(address,idem));
CREATE INDEX IF NOT EXISTS compute_usage ON compute_requests(address,created,state);
CREATE TABLE IF NOT EXISTS compute_responses(request_id TEXT PRIMARY KEY REFERENCES compute_requests(id),encrypted TEXT NOT NULL,content_type TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_models(id TEXT PRIMARY KEY,definition TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_route_health(route TEXT PRIMARY KEY,state TEXT NOT NULL,checked INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_deposits(hash TEXT NOT NULL,log_index INTEGER NOT NULL,address TEXT NOT NULL,amount TEXT NOT NULL,credits INTEGER NOT NULL,block_number TEXT NOT NULL,block_hash TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(hash,log_index));
CREATE TABLE IF NOT EXISTS compute_workers(id TEXT PRIMARY KEY,address TEXT NOT NULL REFERENCES compute_accounts(address),name TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,created INTEGER NOT NULL,last_seen INTEGER,gpu_report TEXT,revoked INTEGER);
CREATE TABLE IF NOT EXISTS compute_reconnects(id TEXT PRIMARY KEY,worker_id TEXT NOT NULL REFERENCES compute_workers(id),candidate_hash TEXT NOT NULL,code_hash TEXT NOT NULL,expires INTEGER NOT NULL,approved INTEGER,consumed INTEGER);
CREATE TABLE IF NOT EXISTS compute_rounds(id TEXT PRIMARY KEY,epoch INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('open','won','expired')),bits INTEGER NOT NULL,work_units INTEGER NOT NULL,opened INTEGER NOT NULL,closed INTEGER,winner_share TEXT,reward TEXT,snapshot TEXT,policy_hash TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS compute_one_round ON compute_rounds(epoch) WHERE state='open';
CREATE TABLE IF NOT EXISTS compute_jobs(id TEXT PRIMARY KEY,worker_id TEXT NOT NULL REFERENCES compute_workers(id),round_id TEXT NOT NULL REFERENCES compute_rounds(id),header TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL,epoch INTEGER NOT NULL,policy_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS compute_shares(id TEXT PRIMARY KEY,job_id TEXT UNIQUE NOT NULL REFERENCES compute_jobs(id),worker_id TEXT NOT NULL REFERENCES compute_workers(id),address TEXT NOT NULL,round_id TEXT NOT NULL REFERENCES compute_rounds(id),epoch INTEGER NOT NULL,proof_hash TEXT UNIQUE NOT NULL,proof TEXT NOT NULL,accepted INTEGER NOT NULL,round_won INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS compute_epochs(epoch INTEGER PRIMARY KEY,manifest TEXT NOT NULL,root TEXT NOT NULL,budget TEXT NOT NULL,state TEXT NOT NULL,tx_hash TEXT,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_migration(id INTEGER PRIMARY KEY CHECK(id=1),manifest TEXT NOT NULL,root TEXT NOT NULL,snapshot_hash TEXT NOT NULL,total TEXT NOT NULL,cutoff_epoch INTEGER NOT NULL,created INTEGER NOT NULL,published_tx TEXT);
CREATE TABLE IF NOT EXISTS compute_gpu_models(id TEXT PRIMARY KEY,definition TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS compute_gpu_approvals(worker_id TEXT PRIMARY KEY REFERENCES compute_workers(id),models TEXT NOT NULL,approved INTEGER NOT NULL,revoked INTEGER);
CREATE TABLE IF NOT EXISTS compute_gpu_jobs(id TEXT PRIMARY KEY,request_id TEXT UNIQUE NOT NULL REFERENCES compute_requests(id),address TEXT NOT NULL,model TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,result TEXT,created INTEGER NOT NULL,expires INTEGER NOT NULL,completed INTEGER);
CREATE TABLE IF NOT EXISTS compute_gpu_leases(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES compute_gpu_jobs(id),worker_id TEXT NOT NULL REFERENCES compute_workers(id),address TEXT NOT NULL,secret_hash TEXT NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL,result TEXT,result_hash TEXT,created INTEGER NOT NULL,UNIQUE(job_id,address));
CREATE TABLE IF NOT EXISTS compute_operator_journal(id TEXT PRIMARY KEY,kind TEXT NOT NULL,reference TEXT UNIQUE NOT NULL,state TEXT NOT NULL,payload TEXT NOT NULL,tx_hash TEXT,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS compute_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,reference TEXT NOT NULL,details TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS compute_epoch_wallets ON compute_shares(epoch,address);
